    @method_decorator("node_alias")
    def setup_node(self):
        self.admin: NodeAdmin = self.create_node_admin_connection()
        self.scf_file = self.get_scf_file()
        self.scf = scf()
        self.scf.load_scf(self.scf_file)
        self.mplane = self.get_node_mplane()
        self.x2_linked_btses = self.set_x2_linked_btses()
        self.watchdog_config = self._create_bts_config()
        self._ssh_vm_connection = self._ssh.connect_to(hostname=self.vm.get("host"), username=self.vm.get("user"),
                                                       password=self.vm.get("password"))
        self.dcap = DcapManager(node_id=self.mrbts_id, node_mplane=self.mplane,
                                dcap_host=self.dcap_host if self.dcap_host else self.vm.get("host"),
                                vm_connection=self._ssh_vm_connection if not self.dcap_host else None,
                                dcap_port=self.dcap_port,
                                custom_profiles=self.dcap_custom_profiles) if self.use_dcap else None
        self.btslog = BtsLogCollector()
        self.aashell = AashellLogCollector(self.vm, self.secondary_vm, self.bts_host_ip)
        self.airphone_logs_collector = AirphoneLogsCollector(self.airphone_details) if self.airphone_details else None
        self.btsverify = NodeStateVerifier(self.mrbts_id, self.node_alias, self._ssh_vm_connection, self.admin,
                                           self.ssh_manager, self.watchdog, self.critical_alarms, self.allowed_alarms,
                                           self.test_specific_alarms, self.watchdog_config, self.logs_dir, self.mplane,
                                           self.scf_file, self.check_mplane, self.detailed_console_log,
                                           self.x2_linked_btses, self.check_amf)
        self.logsverify = NodeLogsVerifier(self.node_alias, self.admin, self.ssh_manager, self.watchdog,
                                           self.watchdog_config, self.use_dcap, self.dcap, self.btslog, self.aashell,
                                           self.verify_syslog, self.syslog_ignored_prints,
                                           self.user_syslog_suspicious_prints, self.detailed_console_log,
                                           self.airphone_logs_collector)
        self.radioModules = self.btsverify.rmod_verifier.modules
        self.shared_radioModules = self.btsverify.rmod_verifier.shared_radioModules
        self.basebandModules = self.btsverify.bbmod_verifier.modules
        self.systemModules = self.btsverify.smod_verifier.modules
        self.cells_per_rat = self.btsverify.cells_verifier.cells_per_rat
        self._ssh_secondary_vm_connection = self._ssh.connect_to(
            hostname=self.secondary_vm.get('host'), username=self.secondary_vm.get('user'),
            password=self.secondary_vm.get('password')) if self.secondary_vm else None
        self.backup_swconfig_path_primary_smod = self.get_swconfig(self.logs_dir,
                                                                   f"primary_smod_swconfig_{self.node_alias}.txt")
        self.backup_swconfig_path_secondary_smod = self.get_swconfig(self.logs_dir,
                                                                     f"secondary_smod_swconfig_{self.node_alias}.txt",
                                                                     True) \
            if self.ssh_manager.is_slave_smod() else None
        self.check_swconfig()
        self.uboot = CSV4ALLUboot(self.ssh_manager, self.systemModules, self.basebandModules)
        self.set_current_reset_counter()
        self.set_cells_if_serial_console_activated()
        self.sync_master = self.is_node_master_sync()
        self.ru_manager = self.setup_ru_manager()

