    @method_decorator("node_alias")
    def start_watching_alarms(self, ignore_gps=False):
        try:
            self.start_timestamp_cni_127210()
            self.watchdog.stop_watching_alarms()
        except Exception as e:
            test_logger(e, "warn", console=False)
            test_logger(traceback.format_exc(), log_level="debug", console=False)

        finally:
            allowed_alarms = self.allowed_alarms + self.temporary_allowed_alarms + self.test_specific_alarms
            self.watchdog.watch_alarms(bts_config=self.watchdog_config, allowed_alarms=allowed_alarms, interval=0.5,
                                       reconnect=True, log_dir=self.admin.admin_logs_dir,
                                       timeout=self.admin_setup_timeout)
            if not ignore_gps:
                time.sleep(2)
                if self.watchdog.is_alarm_active(fault_id="4420"):
                    test_logger("GPS Firmware Ongoing - Waiting up to 25 min for it to finish", log_level="INFO")
                    self.watchdog.wait_for_inactive_alarm(fault_id="4420", timeout=1500)
                self.btsverify.gps_check()

