    @method_decorator("node_alias")
    def restore_swconfig(self):
        self.put_swconfig_to_smod(self.backup_swconfig_path_primary_smod)
        if self.ssh_manager.is_slave_smod():
            self.put_swconfig_to_smod(self.backup_swconfig_path_secondary_smod, True)

    @method_decorator("node_alias")
    def add_hwf_flag_to_swconfig(self):
        backup_swconfig_list = filter(None, [self.backup_swconfig_path_primary_smod,
                                             self.backup_swconfig_path_secondary_smod])
        for backup_swconfig in backup_swconfig_list:
            smod_side = "primary" if "primary" in backup_swconfig else "secondary"
            modified_swconfig = f"{self.logs_dir}/modified_swconfig_{smod_side}.txt"
            with open(backup_swconfig, "r") as swconfig_bk, open(modified_swconfig, "w") \
                    as new_swconfig:
                for line in swconfig_bk:
                    if RFRL_TRUNK_HWF_FLAG.split("=")[0] == line or RFRL_BRANCH_HWF_FLAG.split("=")[0] == line:
                        continue
                    new_swconfig.write(line)
                new_swconfig.write(f"\n{RFRL_TRUNK_HWF_FLAG} #UUF4ALL Site Reset Test flag")
                new_swconfig.write(f"\n{RFRL_BRANCH_HWF_FLAG} #UUF4ALL Site Reset Test flag")
            self.put_swconfig_to_smod(modified_swconfig, slave_smod=True if smod_side == "secondary" else False)

    @method_decorator("node_alias")
    def perform_uboot_downgrade(self):
        if not self.uboot_downgrade():
            return False
        if self.uboot.perform_reset:
            try:
                test_logger(f"[{self.node_alias}] Resetting site after uboot downgrade")
                self.reset_site()
                self.verify_node_bts_state()
                self.start_watching_alarms()
                self.verify_node_state()
                if not self.recheck_uboot_results():
                    return False
                test_logger(f"[{self.node_alias}] UBOOT PASSED", hyperlink=True)
            except Exception as e:
                test_logger(e, "error")
                return False
        return True

    @method_decorator("node_alias")
    def uboot_downgrade(self):
        try:
            test_logger(f"[{self.node_alias}] Uboot Downgrade check")
            self.uboot.uboot_downgrade()
            return True
        except UbootDowngradeError as downgrade_error:
            test_logger("Uboot/Bios downgrade failed, checking if BTS is ok to continue testing", "error")
            test_logger(downgrade_error, "error")
            test_logger(traceback.format_exc(), "debug", console=False)
            return False

    @method_decorator("node_alias")
    def recheck_uboot_results(self):
        attempt_try = 3
        for attempt in range(1, attempt_try + 1):
            recheck_results = self.uboot.uboot_downgrade(verify=True)
            test_logger(f"{attempt}: Recheck result:\n{recheck_results}", console=False)
            if "FW downgraded successfully" not in recheck_results:
                if attempt == attempt_try:
                    test_logger("FW not updated after reset site", "WARN")
                    return False
                time.sleep(60)
                continue
            return True
        return None

