    @method_decorator("node_alias")
    def get_requested_ru_sw(self) -> dict:

        def get_scf_object():
            mrbts_id = self.mrbts_id.replace("MRBTS-", "")
            for np_nr in range(1, 10):
                try:
                    current_object = f"/MRBTS-1/RAT-1/BTS_L-1/BTS_CONF-1/NP-{np_nr}/SCF-1/MRBTS_A-{mrbts_id}/MNL_A-1"
                    self.admin.get_parameters(current_object, pattern=".*")
                    return current_object
                except AdminApiProcedureFailureException:
                    continue
            return None

        infomodel_object = get_scf_object()
        try:
            requested_ru_sw = self.admin.get_parameters(infomodel_object, pattern="requestedRUSW")
            return requested_ru_sw["requestedRUSW"]
        except AdminApiProcedureFailureException as e:
            test_logger(str(e), "DEBUG")
            if 'Object not found' in str(e):
                test_logger(f"Parameter requestedRUSW doesn't exist under {infomodel_object}",
                            "INFO", console=False)
            return {}
        except Exception as e:
            test_logger(e, "ERROR")
            return {}

