    @method_decorator("node_alias")
    def check_swconfig(self):
        raise_message = ""
        for path in [swconfig for swconfig in [self.backup_swconfig_path_primary_smod,
                                               self.backup_swconfig_path_secondary_smod] if swconfig]:
            swconfig_name = path.split('/')[-1].replace("_", " ").replace(".txt", "")
            btslog_flag = ['0x10041=2', '0x10041=5'] if 'primary' in swconfig_name else ['0x10041=2']
            with open(path, "r") as swconfig:
                parsed_flag_list = [flag.lower().split("#")[0].strip().replace(" ", "")
                                    for flag in swconfig.readlines() if not flag.startswith("#")]
                flags_in_swconfig = any(flag in parsed_flag_list for flag in btslog_flag)
                if not parsed_flag_list:
                    raise_message += f"Swconfig: {swconfig_name} is empty!!! "
                elif not flags_in_swconfig:
                    if 'secondary' in swconfig_name and '0x10041=5' in parsed_flag_list:
                        test_logger("Flag 0x10041 on secondary core should have value 2", "WARN")
                    else:
                        raise_message += (f"Mandatory flag {' or '.join(btslog_flag)} "
                                          f"doesn\'t exist in {swconfig_name}!!!")
                else:
                    test_logger(f"Checking {swconfig_name} passed")
        if raise_message:
            test_logger(raise_message, "ERROR")

