    def _check_if_paths_are_similar(self) -> bool:
        target_split = self.target_sw.split("_")[:-1]
        source_split = self.source_sw.split("_")[:-1]
        sw_differences = int(target_split[-1]) - int(source_split[-1])
        if "_".join(target_split[:-1]) == "_".join(source_split[:-1]) and abs(sw_differences) < 2:
            return True
        return False

