    @method_decorator("node_alias")
    def set_fdsw_builds(self, test_phase, slave: bool = False):
        def set_fdsw_builds_for_smods(fdsw_dnr_dir):
            smod = list(self.systemModules.keys())[0 if not slave else 1]
            smod = f"{self.systemModules[smod].get('Module Type')}-{smod.split('-')[-1]}"
            if not fdsw_dnr_dir:
                test_logger(f"DnR partition is not discovered on {smod}, check {test_phase} is skipped")
                return
            sed_fdsw_build = "| awk '/BD/ && /FDSW/ && /xml.p7/' | " \
                             "sed 's/^.*\(LN_WN_FDSW.*xml\).*$/\\1/;s:.xml::' | head -n 1"
            self.fdsw_builds[smod][test_phase] = {'fs3': '', 'active': '', 'passive': ''}
            self.fdsw_builds[smod][test_phase]["fs3"] = \
                self.ssh_manager.execute_command(f"ls -l {fdsw_dnr_dir} {sed_fdsw_build}", slave_smod=slave).rstrip()
            self.fdsw_builds[smod][test_phase]["active"] = \
                self.ssh_manager.execute_command(f"ls -l /ffs/run/ {sed_fdsw_build}", slave_smod=slave).rstrip()
            self.fdsw_builds[smod][test_phase]["passive"] = \
                self.ssh_manager.execute_command(f"ls -l /ffs/stb/ {sed_fdsw_build}", slave_smod=slave).rstrip()
            if self.fdsw_builds[smod][test_phase]["fs3"] != self.fdsw_builds[smod][test_phase]["active"] and \
                    fdsw_dnr_dir == "/ffs/dnr":
                self.ssh_manager.execute_command("systemctl stop ffs-dnr.mount", slave_smod=slave)
                self.ssh_manager.execute_command("rmdir /ffs/dnr", slave_smod=slave)
                self.ssh_manager.execute_command("systemctl start ffs-fs3.mount", slave_smod=slave)

        dnr_dir = self.mount_and_get_dnr_partition(slave)
        set_fdsw_builds_for_smods(dnr_dir)
        test_logger(f"FDSW builds: {json.dumps(self.fdsw_builds, indent=4)}", "DEBUG")

    @method_decorator("node_alias")
    def mount_and_get_dnr_partition(self, is_slave: bool = False) -> str:
        try:
            if self.ssh_manager.execute_command("df -h | grep dnr", slave_smod=is_slave):
                dnr_dir = "/ffs/dnr"
            elif self.ssh_manager.execute_command("df -h | grep fs3 | awk '{print $6}'", slave_smod=is_slave):
                dnr_dir = "/ffs/fs3"
            else:
                self.ssh_manager.execute_command("systemctl start ffs-fs3.mount", slave_smod=is_slave)
                dnr_dir = "/ffs/fs3"

            test_logger(f"DnR mount directory: {dnr_dir}", "DEBUG")
            return dnr_dir
        except Exception as e:
            test_logger(e, "error")
            return ""

    @method_decorator("node_alias")
    def is_smod_pingable(self, smod_ip: Optional[str] = "192.168.255.129", ping_attempts: Optional[int] = 2) -> bool:
        """
        Checks if the SMOD module is reachable via ping.
        Args:
            smod_ip (str, optional): The IP address of the SMOD module. Defaults to "192.168.255.129".
            ping_attempts (int, optional): The number of ping attempts to make. Defaults to 2.
        Returns:
            bool:
                - True: If the SMOD module responded to at least one ping.
                - False: If the SMOD module did not respond to any ping attempts.
        """
        for _ in range(ping_attempts):
            try:
                if "1 received" in self._ssh_vm_connection.execute(f"ping -c 1 {smod_ip}"):
                    return True
                time.sleep(1)
            except Exception as e:
                test_logger(f"is_smod_pingable exception: {e}", "DEBUG")
                if "cannot send command: not connected" in e:
                    raise Exception(
                        f"Connection issue detected with the VM. Verify if the test is running on the VM with an active "
                        f"LMP connection to the target module.")
        return False

