    @method_decorator("node_alias")
    def wait_till_sw_download_finish(self):
        def get_btsl_side():
            internal_id = [self.systemModules[smod].get("Internal Id") for smod in self.systemModules][0]
            bts_l_side_match = re.search(r"RUNTIME_VIEW-[1-4]", internal_id)
            return bts_l_side_match.group(0).split("-")[-1] if bts_l_side_match else "1"

        def verify_sw_download_status():
            sw_status = self.admin.get_parameters(f"/MRBTS-1/RAT-1/SWM-{get_btsl_side()}", pattern=".*"). \
                get("swDownloadInfo").get("state")
            if sw_status != "Finished":
                raise SoftwareStatusError(f"SW Download has not yet finished, status: {sw_status}")

        try:
            wait_until_success(1800, 10, verify_sw_download_status)
        except FunctionTimeoutException as e:
            test_logger(e, "ERROR")

