    @method_decorator("node_alias")
    def remove_hwf_flag_if_exists(self) -> bool:
        put_modified_swconfig = False
        for path in [swconfig for swconfig in [self.backup_swconfig_path_primary_smod,
                                               self.backup_swconfig_path_secondary_smod] if swconfig]:
            swconfig_name = path.split('/')[-1].replace("_", " ").replace(".txt", "")
            hwf_flags = ['0x4f0214=0', '0x190030=0']
            with open(path, "r") as swconfig:
                swconfig_lines = swconfig.readlines()
            new_path = path.replace('.txt', '-modified.txt')
            with open(new_path, 'w') as new_swconfig:
                for sw_flag in swconfig_lines:
                    parsed_flag = [sw_flag.lower().split("#")[0].strip().replace(" ", "")
                                   if not sw_flag.startswith("#") else sw_flag]
                    if not any(flag in parsed_flag for flag in hwf_flags):
                        new_swconfig.write(sw_flag)
                    else:
                        test_logger(f"This flag will be removed from {swconfig_name}: {sw_flag.rstrip()}", "WARN")
                        put_modified_swconfig = True
            if put_modified_swconfig:
                self.put_swconfig_to_smod(new_path, slave_smod=True if new_path.startswith('secondary') else False)
            else:
                os.remove(new_path)
        return put_modified_swconfig

