    @method_decorator("node_alias")
    def setup_ru_manager(self):
        if self.ru_manager_yaml_file:
            if Path(self.ru_manager_yaml_file).is_file():
                test_logger("Performing Setup RU")
                return RUInterface(ssh_manager=self.ssh_manager,
                                   node_rmods=self.radioModules,
                                   smod_ip=self.bts_host_ip,
                                   smod_username=self.node_ssh_username,
                                   smod_password=self.node_ssh_password,
                                   rmod_setup_yaml_path=self.ru_manager_yaml_file)
            else:
                test_logger("Provided path to ru manager yaml file is incorrect!", "ERROR")
        return None

    @method_decorator("node_alias")
    def update_ru_ip_address(self):
        rmods_parameters = self.admin.get_parameters_for_all("RMOD")
        if self.ru_manager:
            for ru_serial, ru_details in self.ru_manager.rmod_connections.items():
                ru_ip_address = self.btsverify.rmod_verifier.get_rmod_ip_address_from_ims(rmods_parameters, ru_serial)
                self.ru_manager.rmod_connections[ru_serial].ip_address = ru_ip_address

    @method_decorator("node_alias")
    def execute_commands_on_rmods(self):
        self.update_ru_ip_address()
        if self.ru_manager:
            try:
                wait_until_success(600, 10, self.ru_manager.execute_commands_on_rmods, fail_on_error=True)
            except FunctionTimeoutException:
                test_logger(f"[{self.node_alias}] Executing commands on radio modules failed", "ERROR")

    @method_decorator("node_alias")
    def add_flags_on_rmods(self):
        self.update_ru_ip_address()
        if self.ru_manager:
            for rmod_instance in self.ru_manager.rmod_connections.values():
                if rmod_instance.supported:
                    if rmod_instance.flags_to_add:
                        test_logger(f"[{self.node_alias}] Adding flags on radio modules")
                        break
            self.ru_manager.add_flags_to_rmods()

    @method_decorator("node_alias")
    def restore_flags_on_rmods(self):
        self.update_ru_ip_address()
        if self.ru_manager:
            for rmod_instance in self.ru_manager.rmod_connections.values():
                if rmod_instance.restore_flags and rmod_instance.supported:
                    test_logger(f"[{self.node_alias}] Restoring flags on radio modules")
                    break
            self.ru_manager.restore_flags_on_rmods()

    @method_decorator("node_alias")
    def download_blackbox_files_from_rmods(self, target_dir: str):
        if self.ru_manager:
            test_logger(f"[{self.node_alias}] Downloading blackbox files from radio modules")
            self.ru_manager.get_blackbox_files_from_rmods(target_dir)

    @method_decorator("node_alias")
    def ru_blackbox_verification(self):
        if self.ru_manager:
            for rmod_instance in self.ru_manager.rmod_connections.values():
                if rmod_instance.verify_blackbox:
                    test_logger(f"[{self.node_alias}] Verification RU Blackbox")
                    break
            self.ru_manager.verify_ru_blackbox()

    @method_decorator("node_alias")
    def verify_ru_blackbox(self, target_dir: str):
        self.update_ru_ip_address()
        try:
            self.download_blackbox_files_from_rmods(target_dir)
            self.ru_blackbox_verification()
        except Exception as e:
            raise RuBlackboxVerificationFailed(e)
